alter table public.contact_sources add column if not exists fetched_at timestamptz;
alter table public.contact_sources add column if not exists source_kind text;
alter table public.contact_research_runs add column if not exists queries_executed integer not null default 0;
alter table public.contact_research_runs add column if not exists sources_discovered integer not null default 0;
alter table public.contact_research_runs add column if not exists blocked_sources integer not null default 0;
alter table public.contact_research_runs add column if not exists new_claims integer not null default 0;
alter table public.contact_research_runs add column if not exists new_works integer not null default 0;
alter table public.contact_research_runs add column if not exists new_positions integer not null default 0;
alter table public.contact_research_runs add column if not exists new_education integer not null default 0;
alter table public.contact_research_runs add column if not exists new_problems integer not null default 0;
alter table public.contact_research_runs add column if not exists new_themes integer not null default 0;
alter table public.contact_research_runs add column if not exists new_jtbd integer not null default 0;
alter table public.contact_research_runs add column if not exists completeness_before integer;
alter table public.contact_research_runs add column if not exists completeness_after integer;
alter table public.contact_research_runs add column if not exists error_code text;
alter table public.contact_research_runs drop constraint if exists contact_research_runs_status_check;
